import{g as s,ad as a,r as o,A as t}from"./chunks/framework.79nw0c7c.js";const u=JSON.parse('{"title":"Tailwind Setup","description":"","frontmatter":{},"headers":[],"relativePath":"docs/foundations/tailwind.md","filePath":"docs/foundations/tailwind.md","lastUpdated":1789601167000}'),n={name:"docs/foundations/tailwind.md"};function d(c,e,p,i,l,r){return a(),o("div",null,[...e[0]||(e[0]=[t(`<h1 id="tailwind-setup" tabindex="-1">Tailwind Setup <a class="header-anchor" href="#tailwind-setup" aria-label="Permalink to “Tailwind Setup”">​</a></h1><p><code>frappe-ui</code> ships as a Tailwind v3 preset. Add it to your app&#39;s <code>tailwind.config.js</code>:</p><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_edvzsf">import</span><span class="s_4q1z3w"> preset</span><span class="s_1jjt6x">,</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">content</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui/tailwind</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"></span>
<span class="line"><span class="s_edvzsf">export</span><span class="s_edvzsf"> default</span><span class="s_13ahmt"> {</span></span>
<span class="line"><span class="s_r4oegk">  presets</span><span class="s_1jjt6x">:</span><span class="s_13ahmt"> [</span><span class="s_11933w">preset</span><span class="s_13ahmt">]</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_r4oegk">  content</span><span class="s_1jjt6x">:</span><span class="s_13ahmt"> [</span><span class="s_fjrnv8">...</span><span class="s_11933w">content</span><span class="s_1jjt6x">,</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">./src/**/*.{vue,js,ts,jsx,tsx}</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt">]</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_13ahmt">}</span></span></code></pre></div><p>The preset sets <code>darkMode</code>, the spacing scale, the <code>prose</code> / <code>prose-v3</code> typography safelist, and four plugins (<code>@tailwindcss/forms</code>, <code>@tailwindcss/typography</code>, the theme plugin, the Lucide icon plugin). That&#39;s the whole exported surface — a default export (the preset) and the named <code>content</code> export below.</p><p>Requires <strong>Tailwind <code>&gt;=3.4.0 &lt;4</code></strong>. It is a peer dependency. Tailwind v4 reads none of this shape, so the design tokens never load there.</p><h2 id="what-the-preset-replaces" tabindex="-1">What the preset replaces <a class="header-anchor" href="#what-the-preset-replaces" aria-label="Permalink to “What the preset replaces”">​</a></h2><p>Five theme sections are <strong>replaced</strong>, not extended:</p><table tabindex="0"><thead><tr><th>Section</th><th>What you get</th><th>What you lose</th></tr></thead><tbody><tr><td><code>colors</code></td><td>the frappe-ui palette (<code>ink-*</code>, <code>surface-*</code>, <code>outline-*</code>, and the raw ramps)</td><td>Tailwind&#39;s stock palette (<code>slate</code>, <code>sky</code>, <code>emerald</code>, …)</td></tr><tr><td><code>fontSize</code></td><td>the type scale (<code>text-sm</code>, <code>text-base</code>, <code>text-lg</code>, …, at frappe-ui&#39;s values)</td><td>Tailwind&#39;s sizes and their paired line heights</td></tr><tr><td><code>screens</code></td><td><code>sm</code> 640px, <code>md</code> 768px, <code>lg</code> 1024px, <code>xl</code> 1280px</td><td><code>2xl:</code></td></tr><tr><td><code>borderRadius</code></td><td>the numbered scale (<code>rounded-4</code>, <code>rounded-9</code>, …)</td><td><code>rounded-sm</code> … <code>rounded-3xl</code></td></tr><tr><td><code>boxShadow</code></td><td>the elevation scale (<code>shadow-sm</code> … <code>shadow-2xl</code>, each a <code>--elevation-*</code> variable)</td><td><code>shadow-inner</code></td></tr></tbody></table><p>A class from a replaced section is simply not generated. <code>2xl:flex</code> and <code>shadow-inner</code> compile to nothing, with no error. Everything else (<code>spacing</code>, <code>textColor</code>, <code>backgroundColor</code>, and the rest) is <strong>extended</strong>, so Tailwind&#39;s own values stay.</p><h2 id="the-spacing-scale" tabindex="-1">The spacing scale <a class="header-anchor" href="#the-spacing-scale" aria-label="Permalink to “The spacing scale”">​</a></h2><p>Every integer from <code>1</code> to <code>128</code> and every half step from <code>0.5</code> to <code>19.5</code>, all at the canonical <code>0.25rem</code> step. Stock Tailwind has gaps above <code>12</code> (<code>13</code>, <code>15</code>, <code>17</code>, <code>18</code>, <code>19</code>, <code>21</code>… are undefined), so <code>h-17</code> and <code>size-17</code> silently do not compile there.</p><p>The scale is declared once. Tailwind 3.4 reads <code>theme(&#39;spacing&#39;)</code> for <code>width</code>, <code>height</code>, <code>size</code>, <code>minWidth</code>, <code>maxWidth</code>, <code>minHeight</code> and <code>maxHeight</code>, so <code>w-17</code>, <code>min-w-40</code>, <code>max-h-52</code> and <code>size-3.5</code> all come from the same numbers. The list styling hooks read it too: <code>list-gap-3</code> and <code>list-row-px-2.5</code> take any spacing key.</p><h2 id="why-you-have-to-list-content-yourself" tabindex="-1">Why you have to list <code>content</code> yourself <a class="header-anchor" href="#why-you-have-to-list-content-yourself" aria-label="Permalink to “Why you have to list content yourself”">​</a></h2><p>Tailwind v3 does not merge a preset&#39;s <code>content</code> into your app&#39;s config — it only reads the top-level <code>content.files</code> array. A preset can ship <code>theme</code> and <code>plugins</code>, which do merge, but not <code>content</code>. This is a Tailwind v3 limitation, not a choice <code>frappe-ui</code> makes.</p><p>That means every app consuming <code>frappe-ui</code> has to know which of its source folders emit Tailwind classes and list them itself. Left hand-maintained, that list drifts: two apps on <code>frappe-ui@1.0.0-beta</code> only glob <code>src/components/**</code>, missing <code>src/molecules/</code> entirely — every utility class the editor and list molecules emit never gets compiled into those apps&#39; CSS. The exported list mirrors this repo&#39;s own <code>tailwind.config.js</code> <code>content</code> array, so the two can&#39;t drift apart from each other either.</p><h2 id="the-content-export" tabindex="-1">The <code>content</code> export <a class="header-anchor" href="#the-content-export" aria-label="Permalink to “The content export”">​</a></h2><p><code>frappe-ui/tailwind</code> exports the glob list it needs as <code>content</code>, so your <code>content</code> array becomes &quot;the library&#39;s globs, plus mine&quot; instead of a hand-copied path list:</p><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">content</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui/tailwind</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"></span>
<span class="line"><span class="s_22m8k2">console</span><span class="s_1jjt6x">.</span><span class="s_indoxt">log</span><span class="s_13ahmt">(</span><span class="s_22m8k2">content</span><span class="s_13ahmt">)</span></span>
<span class="line"><span class="s_1th9sy">// [</span></span>
<span class="line"><span class="s_1th9sy">//   &#39;.../frappe-ui/src/**/*.{vue,js,ts,jsx,tsx}&#39;,</span></span>
<span class="line"><span class="s_1th9sy">//   &#39;.../frappe-ui/icons/**/*.{vue,js,ts,jsx,tsx}&#39;,</span></span>
<span class="line"><span class="s_1th9sy">//   &#39;.../frappe-ui/experimental/Accordion/**/*.{vue,js,ts,jsx,tsx}&#39;,</span></span>
<span class="line"><span class="s_1th9sy">//   … one glob per re-exported experimental directory, then vitepress</span></span>
<span class="line"><span class="s_1th9sy">// ]</span></span></code></pre></div><p>One rule decides what is listed under <code>experimental/</code>: every directory the <code>frappe-ui/experimental</code> barrel re-exports. Today that is <code>Accordion</code>, <code>Calendar</code>, <code>Charts</code>, <code>CommandPalette</code>, <code>FloatingWindow</code>, <code>ListView</code>, <code>MultiEmailInput</code>, <code>SpriteIcons</code>, <code>TextEditor</code> and <code>ThemeSwitcher</code>. Importing any of them pulls that directory&#39;s classes into your build, so they have to be scanned. A test derives the list from the barrel, so the two cannot drift. Directories the barrel does not re-export stay out, because nothing you can import reaches them.</p><p><code>vitepress/**</code> is listed for the same reason on its own subpath: a docs site built on <code>frappe-ui/vitepress</code> has no other way to emit the theme&#39;s classes.</p><p>The paths are resolved against wherever <code>frappe-ui</code> is actually installed (<code>node_modules</code>, a monorepo symlink, a local workspace checkout), so they work regardless of your app&#39;s working directory. When <code>frappe-ui</code> adds a new source directory that emits classes, bumping the dependency picks up the new glob automatically — you don&#39;t need to touch your <code>tailwind.config.js</code> again.</p><h2 id="hover-styles" tabindex="-1">Hover styles <a class="header-anchor" href="#hover-styles" aria-label="Permalink to “Hover styles”">​</a></h2><p>The preset sets <code>future.hoverOnlyWhenSupported</code>, so <code>hover:</code> compiles under <code>@media (hover: hover) and (pointer: fine)</code> and applies only on a device that can point at something. Without it a phone applies <code>:hover</code> on tap and keeps it until the next tap lands elsewhere, so a ghost button a thumb touched stayed filled. A laptop with a touchscreen answers <code>(hover: hover)</code> and keeps both.</p><p>That leaves a rule for anything shown only on hover: it needs a touch path, because the sticky tap-hover was the only route a phone ever had to it. Either a tap already reaches what the reveal is for — tapping a sortable header sorts it and its glyph appears, tapping a playing video pauses it and its controls appear — or the device that cannot hover shows it outright:</p><div class="language-html"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">button</span><span class="s_1i4ay4"> class</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">opacity-0 group-hover:opacity-100 [@media(hover:none)]:opacity-100</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2">&gt;</span></span></code></pre></div><p>Do not stand a breakpoint in for hover: <code>sm:opacity-0 sm:group-hover:opacity-100</code> hides the control from a tablet and shows it to a narrow desktop window, and neither is the device the rule is about.</p>`,26)])])}const m=s(n,[["render",d]]);export{u as __pageData,m as default};
